public class NDXUmsCust_ArtGrp extends common
{
}

Method.Source:
/// <summary>
/// DebuC 16.10.23
/// </summary>
/// <param name = "companyId">CompanyId</param>
/// <param name = "salesId">SalesId</param>
/// <param name = "invoiceId">InvoiceId</param>
/// <param name = "goodsId">KCS_GoodsID</param>
/// <param name = "l_forUpdate">boolean</param>
/// <returns>NDXUmsCust_ArtGrp</returns>
static NDXUmsCust_ArtGrp find(CompanyId    companyId,
                           SalesId      salesId,
                           InvoiceId    invoiceId,
                           KCS_GoodsID  goodsId,
                           boolean      l_forUpdate = false)
{
    NDXUmsCust_ArtGrp  umsatz;
    ;
    umsatz.selectForUpdate(l_forUpdate);

    select      umsatz
    where   umsatz.CompanyId    == companyId    &&
            umsatz.SalesId      == salesId      &&
            umsatz.InvoiceId    == invoiceId    &&
            umsatz.GoodsId      == goodsId;

    return umsatz;
}

/// <summary>
/// DebuC 07.08.24
/// </summary>
/// <param name = "company">CompanyId</param>
/// <param name = "jahr">NDXJahr</param>
/// <param name = "monat">NDXMonat</param>
/// <returns>AmountCur</returns>
static AmountCur getMonthLineAmount(CompanyId company, NDXJahr jahr, NDXMonat monat)
{
    NDXUmsCust_ArtGrp      nDXUmsCust_ArtGrp;

    Query                   q = new Query();
    QueryRun                qr;
    QueryBuildDataSource    qbd, qbd2;
    QueryBuildFieldList     fields;
    ;

    qbd     = q.addDataSource(tablenum(NDXUmsCust_ArtGrp));

    fields = qbd.fields();
    fields.addField(fieldnum(NDXUmsCust_ArtGrp, LineAmount), SelectionField::Sum);

    qbd2 = qbd.addDataSource(tablenum(NDXUmsCust));
    //--> 1.1: NDX/PAFFH/NDX_TASK1235003686/07.05.2014
    qbd2.addLink(FieldNum(NDXUmsCust_ArtGrp, CompanyId), fieldnum(NDXUmsCust, CompanyId));
    qbd2.addLink(FieldNum(NDXUmsCust_ArtGrp, SalesId), fieldnum(NDXUmsCust, SalesId));
    //<-- NDX/PAFFH/NDX_TASK1235003686/07.05.2014
    qbd2.addLink(FieldNum(NDXUmsCust_ArtGrp, InvoiceId), fieldnum(NDXUmsCust, InvoiceId));
    qbd2.joinMode(JoinMode::InnerJoin);
    qbd2.orderMode(OrderMode::GroupBy);
    qbd2.addGroupByField(fieldnum(NDXUmsCust, CompanyId));
    qbd2.addGroupByField(fieldnum(NDXUmsCust, Jahr));
    qbd2.addGroupByField(fieldnum(NDXUmsCust, Month));
    qbd2.addRange(fieldnum(NDXUmsCust, CompanyId)).value(company);
    qbd2.addRange(fieldnum(NDXUmsCust, Jahr)).value(QueryValue(jahr));
    qbd2.addRange(fieldnum(NDXUmsCust, Month)).value(QueryValue(Monat));

    qr = new QueryRun(q);
    qr.next();
    nDXUmsCust_ArtGrp = qr.get(tablenum(NDXUmsCust_ArtGrp));

    return nDXUmsCust_ArtGrp.LineAmount;

}
